function appealCopy(v){return JSON.parse(JSON.stringify(v))}
function appealById(p,id){return (p.evaluationAppeals||[]).find(a=>a.id===id)}
function appealReviewer(p,a){return uid==='d1'&&uid!==a.requester&&uid!==p.evaluations[a.student]?.by&&uid!==a.revision?.by}
function appealCurrent(p,a){return !!p.evaluations[a.student]?.final&&(p.evaluations[a.student].version||1)===a.evaluationVersion}
function appealEvent(p,a,state,reason){a.state=state;a.events.push({state,reason,by:uid,time:new Date().toISOString()});log(p,'Evaluation appeal '+a.id+' → '+state);closeModal();render()}
function evaluationAppealPanel(p,student){if(!p.evaluations[student]?.final||!(uid===student||mentor(p)||uid==='d1'))return '';let list=(p.evaluationAppeals||[]).filter(a=>a.student===student),active=list.some(a=>!['REJECTED','REVERIFIED'].includes(a.state));return `<details><summary>Evaluation v${p.evaluations[student].version||1} · appeals & amendment history</summary><p>The current evaluation remains official until an approved revision is independently reverified. Demonstration authority: Department Head reviews; assigned mentor prepares the revision.</p>${uid===student&&!active?btn('Request evaluation review',`appealRequestForm('${student}')`):''}${list.map(a=>`<div class="card"><strong>${esc(a.id)}</strong> ${pill(a.state)}<p>Evaluation v${a.evaluationVersion} · ${esc(a.reason)}</p><p>Proposed correction: ${esc(a.correction)}</p>${a.revision?`<h4>Proposed revised evaluation</h4>${evaluationSummary(a.revision)}<p>${esc(a.revision.feedback)}</p><p>${esc(a.revision.reason)}</p><div class="notice">On reverification, any VALID certificate will be superseded with a new reference if eligible, or revoked if the certificate threshold is not met. Already revoked certificates remain revoked.</div>`:''}<div class="buttons">${appealReviewer(p,a)&&a.state==='AMENDMENT_REQUESTED'?btn('Start independent review',`startEvaluationAppeal('${a.id}')`):''}${appealReviewer(p,a)&&a.state==='UNDER_REVIEW'?btn('Record decision',`appealDecisionForm('${a.id}')`):''}${mentor(p)&&a.state==='APPROVED'?btn('Prepare revised version',`appealRevisionForm('${a.id}')`):''}${appealReviewer(p,a)&&a.state==='REVISED_VERSION'?btn('Reverify or return revision',`appealReverifyForm('${a.id}')`):''}</div>${a.events.map(e=>`<p class="meta">${esc(e.state)} · ${esc(name(e.by))} · ${esc(eventTime(e.time))} · ${esc(e.reason)}</p>`).join('')}</div>`).join('')}${(p.evaluationHistory?.[student]||[]).map(ev=>`<div class="card"><h4>Preserved evaluation v${ev.version||1} · SUPERSEDED</h4>${evaluationSummary(ev)}<p>${esc(ev.feedback)}</p></div>`).join('')}</details>`}
function appealRequestForm(student){let p=current();if(uid!==student)return;modal(`<h2>Request evaluation review</h2><p>Review of evaluation v${p.evaluations[student].version||1}.</p><form onsubmit="requestEvaluationAppeal(event,'${student}')"><label>Reason<textarea name="reason" required></textarea></label><label>Proposed correction<textarea name="correction" required></textarea></label><button class="primary">Submit request</button></form>`)}
function requestEvaluationAppeal(e,student){e.preventDefault();let p=current(),ev=p.evaluations[student],f=new FormData(e.target),reason=f.get('reason').trim(),correction=f.get('correction').trim();if(uid!==student||!p.members.includes(student)||!ev?.final||!reason||!correction)return toast('Own finalized evaluation, reason and proposed correction required.');p.evaluationAppeals??=[];if(p.evaluationAppeals.some(a=>a.student===student&&!['REJECTED','REVERIFIED'].includes(a.state)))return toast('An active review already exists.');let a={id:'EA'+Date.now()+'-'+p.evaluationAppeals.length,student,requester:uid,evaluationVersion:ev.version||1,reason,correction,events:[]};p.evaluationAppeals.push(a);appealEvent(p,a,'AMENDMENT_REQUESTED',reason)}
function startEvaluationAppeal(id){let p=current(),a=appealById(p,id);if(!a||!appealReviewer(p,a)||a.state!=='AMENDMENT_REQUESTED'||!appealCurrent(p,a))return toast('Independent reviewer and current evaluation required.');a.reviewer=uid;appealEvent(p,a,'UNDER_REVIEW','Independent review started')}
function appealDecisionForm(id){modal(`<h2>Independent appeal decision</h2><form onsubmit="decideEvaluationAppeal(event,'${id}')"><label>Decision<select name="decision"><option>APPROVED</option><option>REJECTED</option></select></label><label>Decision reason<textarea name="reason" required></textarea></label><p>Approval permits a revision; the current evaluation remains official until reverification.</p><button class="primary">Record decision</button></form>`)}
function decideEvaluationAppeal(e,id){e.preventDefault();let p=current(),a=appealById(p,id),f=new FormData(e.target),decision=f.get('decision'),reason=f.get('reason').trim();if(!a||!appealReviewer(p,a)||a.state!=='UNDER_REVIEW'||!appealCurrent(p,a)||!['APPROVED','REJECTED'].includes(decision)||!reason)return toast('Independent review decision and reason required.');a.decision=decision;a.decisionReason=reason;a.decidedBy=uid;a.decidedAt=new Date().toISOString();appealEvent(p,a,decision,reason)}
function appealRevisionForm(id){let p=current(),a=appealById(p,id);if(!a||!mentor(p)||a.state!=='APPROVED')return;let ev=p.evaluations[a.student],r=ev.rubricSnapshot||legacyRubric();modal(`<h2>Prepare evaluation v${(ev.version||1)+1}</h2><p>Uses the original evaluation rubric: ${esc(r.title)} v${r.version}. The original remains official.</p><form onsubmit="proposeEvaluationRevision(event,'${id}')">${r.criteria.map((c,i)=>`<label>${esc(c.name)} · 0–${c.max}${c.allowNA?' or NA':''}<input name="s${i}" value="${ev.scores[i]===null?'NA':ev.scores[i]}" required></label>`).join('')}<label>Revised feedback<textarea name="feedback" required>${esc(ev.feedback)}</textarea></label><label>Amendment reason<textarea name="reason" required></textarea></label><p>Submitting authorizes the certificate consequence shown to the independent reviewer.</p><button class="primary">Submit revised version for reverification</button></form>`)}
function proposeEvaluationRevision(e,id){e.preventDefault();let p=current(),a=appealById(p,id),f=new FormData(e.target);if(!a||!mentor(p)||uid===a.requester||a.state!=='APPROVED'||!appealCurrent(p,a))return toast('Assigned independent evaluator and approved current request required.');let ev=p.evaluations[a.student],r=ev.rubricSnapshot||legacyRubric(),result;try{result=calculateAssessment(r,r.criteria.map((_,i)=>f.get('s'+i)))}catch(error){return toast(error.message)}let feedback=f.get('feedback').trim(),reason=f.get('reason').trim();if(!feedback||!reason)return toast('Feedback and amendment reason required.');a.revision={...result,feedback,reason,final:true,by:uid,time:new Date().toISOString(),version:(ev.version||1)+1,reflectionVersion:ev.reflectionVersion||p.reflections[a.student]?.version,rubricSnapshot:appealCopy(r),appealId:a.id};appealEvent(p,a,'REVISED_VERSION',reason)}
function appealReverifyForm(id){let p=current(),a=appealById(p,id);if(!a)return;modal(`<h2>Reverify revised evaluation</h2>${evaluationSummary(a.revision)}<p>${esc(a.revision.feedback)}</p><div class="notice">Approval replaces the official evaluation and preserves its original. Any VALID certificate will be superseded with a replacement reference if eligible, or revoked if ineligible. Revoked certificates will not be restored.</div><form onsubmit="reverifyEvaluationRevision(event,'${id}')"><label>Decision<select name="decision"><option>REVERIFIED</option><option>RETURN</option></select></label><label>Verification reason<textarea name="reason" required></textarea></label><button class="primary">Record verification decision</button></form>`)}
function reverifyEvaluationRevision(e,id){e.preventDefault();let p=current(),a=appealById(p,id),f=new FormData(e.target),decision=f.get('decision'),reason=f.get('reason').trim();if(!a||!appealReviewer(p,a)||a.state!=='REVISED_VERSION'||!appealCurrent(p,a)||!reason||!['REVERIFIED','RETURN'].includes(decision))return toast('Independent reverification and current source evaluation required.');if(decision==='RETURN'){a.returnedRevisions??=[];a.returnedRevisions.push(appealCopy(a.revision));delete a.revision;return appealEvent(p,a,'APPROVED','Revision returned: '+reason)}if(!deliveryIndividualReady(p,a.student))return toast('Resolve the approved delivery and session requirements before reverifying this evaluation.');let now=new Date().toISOString(),student=a.student,old=p.evaluations[student];p.evaluationHistory??={};p.evaluationHistory[student]??=[];p.evaluationHistory[student].push({...appealCopy(old),version:old.version||1,status:'SUPERSEDED',supersededAt:now,appealId:a.id});p.evaluations[student]={...appealCopy(a.revision),reverifiedBy:uid,reverifiedAt:now,verificationReason:reason};let c=p.certs[student];if(c?.status==='VALID'){if(a.revision.certificateEligible===false){c.status='REVOKED';c.revokedAt=now;c.revokedBy=uid;c.reason='Reverified evaluation amendment '+a.id;c.evaluationVersion=a.revision.version}else{let version=(c.version||1)+1,root=c.root||c.id,reference=root+'-v'+version;p.certificateHistory??={};p.certificateHistory[student]??=[];p.certificateHistory[student].push({...appealCopy(c),status:'SUPERSEDED',supersededAt:now,replacedBy:reference,reason:'Reverified evaluation amendment '+a.id});p.certs[student]={...appealCopy(c),id:reference,root,version,status:'VALID',issued:now,replaces:c.id,evaluationVersion:a.revision.version,issuer:a.revision.by,issuerName:name(a.revision.by),authorizedBy:uid,correctionReason:'Reverified evaluation amendment '+a.id};delete p.certs[student].replacedBy}}a.reverifiedBy=uid;a.reverifiedAt=now;appealEvent(p,a,'REVERIFIED',reason)}
